% 
% end



% %%等价实现 2：直接用 butter 得到 [b,a] 系数
% function [b, a, Fs] = bpf_vitalsign_ba
% % 返回可用于 filter/filtfilt 的 [b,a] 系数
% 
% Fs  = 20;
% N_total = 4;                 % 期望的总阶数
% Nbp = N_total / 2;           % butter 的带通指定“原型阶数”，带通总阶数=2*Nbp=4
% 
% Fc1 = 0.1;
% Fc2 = 2.0;
% Wn  = [Fc1 Fc2] / (Fs/2);    % 归一化截止到 Nyquist
% 
% [b, a] = butter(Nbp, Wn, 'bandpass');
% 
% % 使用：
% %   y_causal = filter(b, a, x);          % 因果
% %   y_zero   = filtfilt(b, a, x);        % 零相位（离线推荐）
% end